What does this code print? What would happen if the `if node in seen: continue` check were removed, and why might this explicit-stack version be preferred over a recursive DFS on a graph containing a path of a million nodes?

graph = {1: [2, 3], 2: [4], 3: [4], 4: [1]}

def dfs(start):
    seen, stack, order = set(), [start], []
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        order.append(node)
        for nb in graph[node]:
            stack.append(nb)
    return order

print(dfs(1))

This class simulates how a dynamic array such as a Python list grows: when it is full, it moves every item into a new block twice as large and counts the moved items. What does it print? What do the numbers tell you about the cost of a single append and of n appends?

class DynArray:
    def __init__(self):
        self.size, self.cap, self.copies = 0, 1, 0

    def append(self, x):
        if self.size == self.cap:
            self.copies += self.size  # move every item to a bigger block
            self.cap *= 2
        self.size += 1

for n in [16, 17, 1000]:
    arr = DynArray()
    for i in range(n):
        arr.append(i)
    print(n, arr.cap, arr.copies)
